<section class="ld-admin-page-head"><div><span class="ld-admin-kicker">RELATÓRIOS</span><h1>Desempenho dos alunos</h1><p>Resumo acadêmico consolidado por estudante.</p></div><a class="ld-admin-primary-action" href="<?= e(url('/admin/relatorios/exportar')) ?>">Exportar CSV</a></section>
<section class="ld-admin-panel"><div class="ld-admin-table-wrap"><table class="ld-admin-table"><thead><tr><th>Aluno</th><th>Status</th><th>XP / nível</th><th>Progresso</th><th>Quizzes</th><th>Simulados</th><th>Último login</th></tr></thead><tbody><?php if(empty($rows)): ?><tr><td colspan="7">Nenhum aluno cadastrado.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><a class="ld-admin-link" href="<?= e(url('/admin/usuarios/'.(int)$row['id'])) ?>"><strong><?= e($row['name']) ?></strong></a><small><?= e($row['email']) ?></small></td><td><span class="ld-admin-status is-<?= e($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= (int)$row['xp_total'] ?> XP<small>Nível <?= (int)$row['current_level'] ?></small></td><td><?= number_format((float)$row['progress_pct'],1,',','.') ?>%</td><td><?= (int)$row['quiz_attempts'] ?><small>Média <?= number_format((float)$row['quiz_average'],1,',','.') ?>%</small></td><td><?= (int)$row['simulation_attempts'] ?><small>Média <?= number_format((float)$row['simulation_average'],1,',','.') ?>%</small></td><td><?= $row['last_login_at']?e(date('d/m/Y H:i',strtotime($row['last_login_at']))):'Nunca' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
